    // Configure Hub - tile descriptions (system category)
    'SettingsDesc'                        => 'Konfigurer indstillinger for hele systemet: basis-URL, sikkerhed, standardsprog, tidszone, standardindstillinger for risikoscoring og meget mere.',
    'SettingsPreferencesDesc'             => 'Standardværdier og adfærdspræferencer i hele SimpleRisk: sprog, tidszone, revisionsstatusser, krav til risikokortlægning, til/fra-indstillinger for brugerfladens adfærd og lignende.',
    'SettingsFileUploadDesc'              => 'Tilladte filuploadtyper og størrelsesgrænser for de forskellige felter for vedhæftede filer.',
    'SettingsMailDesc'                    => 'SMTP-konfiguration til udgående e-mailnotifikationer, herunder transport, vært, godkendelse og svaradresse.',
    'SettingsBackupsDesc'                 => 'Konfigurer opbevaring, tidsplan og downloadlinks for sikkerhedskopier af SimpleRisk-databasen.',
    'SettingsSecurityDesc'                => 'Godkendelse, session, adgangskodepolitik, basis-URL og API-sikkerhedsindstillinger.',
    'SettingsLoggingDesc'                 => 'Konfiguration af fejlfindings- og revisionslogføring: logniveauer, opbevaring og placering af logfiler.',
    'HealthCheckDesc'                     => 'Diagnosticer systemstatus: PHP-version, udvidelser, filtilladelser, databaseforbindelse, cron-tidsplan og aktiveringer af Extra-moduler.',
    'AnnouncementsDesc'                   => 'Skriv og administrer bannermeddelelser, der er synlige for alle brugere.',
    'RegisterAndUpgradeDesc'              => 'Registrer din SimpleRisk-installation, indtast eller forny en abonnementsnøgle, og udløs Core/Extra-opgraderinger med et enkelt klik.',
    'QueueMonitorDesc'                    => 'Undersøg baggrundsjobkøen: ventende, igangværende og mislykkede job.',
    'ExtrasDesc'                          => 'Aktiver, deaktiver og konfigurer SimpleRisk Extras (betalte tilføjelser).',
    'ArtificialIntelligenceExtraDesc'     => 'Ekstraprogrammet for kunstig intelligens leverer forbedret risikoanalyse (herunder FAIR-vurderinger) og tilpasset dokumentation.',
    'CustomizationExtraDesc'              => 'Tilpasningsfunktionen gør det muligt at tilføje og fjerne forskellige typer felter og dynamisk oprette brugerdefinerede sideskabeloner.',
    'NotificationExtraDesc'               => 'Extra-modulet Email Notification gør det muligt for SimpleRisk at sende e-mailnotifikationer, når risici indsendes, ændres eller på anden måde behandles. Dette Extra-modul kan også tilføjes som et planlagt script, der sender rutinemæssige påmindelser, når risici er klar til en ledelsesgennemgang. I SimpleRisk Core-produktet kommunikeres der uden dette Extra-modul ingen notifikationer uden for selve værktøjet.',
    'VulnerabilityManagementExtraDesc'    => 'Extra-modulet Vulnerability Management giver kunder mulighed for at integrere deres SimpleRisk-instans med Qualys, Tenable.io eller Rapid7 Nexpose/InsightVM og importere både aktiv- og sårbarhedsdata til SimpleRisk. Derfra kan du vælge, hvilke sites du vil dække, bestemme hvilke sårbarhedsscorer der skal importeres, og vurdere hvilke sårbarheder der skal omdannes til risici, så de kan spores.',
    'IncidentManagementExtraDesc'         => 'Extra-modulet Incident Management er baseret på NIST 800-61 Computer Security Incident Handling Guide og giver funktioner til hændelsesstyring direkte i SimpleRisk-systemet.',

    // Configure Hub - tile descriptions (customization category)
    'RedefineNamingConventionsDesc'       => 'Omdøb SimpleRisks terminologi (risiko, aktiv, ramme osv.) i hele brugerfladen.',
    'RiskConfigurationDesc'               => 'Konfigurer risikoscoringsregler: niveauer, appetit, SLA-tærskler og de klassiske/bidragende risikoformler.',
    'RiskAndThreatCatalogDesc'            => 'Vedligehold kataloget over risiko- og trusselsværdier, der bruges i rullemenuer.',
    'AddAndRemoveValuesDesc'              => 'Administrer rullemenuværdierne for risikofelter: placering, kilde, kategori, team, teknologi og mere.',
    'AssetValuationDesc'                  => 'Konfigurer værdiansættelsesskalaen for aktiver og tilsidesættelser af værdiansættelse pr. aktiv.',

    // Configure Hub - tile descriptions (users category)
    'UserManagementDesc'                  => 'Tilføj, rediger, deaktiver og nulstil brugere; administrer adgangskodepolitik.',
    'RoleManagementDesc'                  => 'Definer roller og de tilladelser, som hver rolle giver.',
    'TeamManagementDesc'                  => 'Opret og administrer teams, der bruges til filtrering af synlighed af poster.',
    'SeparationExtraDesc'                 => 'Ekstrafunktionen Teambaseret adskillelse begrænser risikovisning til kun de brugere, der er medlemmer af det team, som risikoen er tildelt. I SimpleRisk Core-produktet kan alle brugere se alle risici uden denne ekstrafunktion.',
    'CustomAuthenticationExtraDesc'       => 'Extra-modulet Custom Authentication understøtter Active Directory- og SAML-autentificering. I SimpleRisk Core-produktet er den eneste mulighed uden dette Extra-modul at oprette nye brugere i SimpleRisks identitetslager.',
    'EncryptionExtraDesc'                 => 'Encrypted Database Extra genererer en tilfældig AES-256-bit krypteringsnøgle og bruger den derefter til at kryptere følsom tekst, før den indsættes i SimpleRisk-databasen. Dette forhindrer nogen i at kunne se eller ændre dataene uden at bruge SimpleRisk-applikationen direkte.',
    'OrganizationManagementDesc'          => 'Extra-modulet Organizational Hierarchy gør det muligt at definere flere forretningsenheder, som kan omfatte et vilkårligt antal teams. Brugere kan derefter tildeles på tværs af ét eller flere teams under forskellige forretningsenheder. Det påvirker en brugers mulighed for at se og bruge de teams, brugere og aktiver, som vedkommende ikke er tilknyttet.',

    // Configure Hub - tile descriptions (data category)
    'DeleteRisksDesc'                     => 'Masseslet risici. Brug sparsomt – sletninger er permanente.',
    'AuditTrailDesc'                      => 'Søg i og eksporter systemets revisionslog over brugerhandlinger.',
    'ImportExportExtraDesc'               => 'Extra-modulet Import-Export giver mulighed for at importere data til SimpleRisk ved at kortlægge felter i en CSV-fil til felter i SimpleRisk-databasen. Det kan bruges til at importere revisionsresultater fra et regneark fra tredjepart, resultater af sårbarhedsscanninger fra et andet værktøj, aktiver fra din CMDB og meget mere. Extra-modulet gør det også muligt at eksportere CSV-filer fra SimpleRisk med risici, afhjælpninger, gennemgange eller en kombinationsrapport over alle tre.',
    'JiraExtraDesc'                       => 'Extra-modulet Jira Integration giver brugere mulighed for tovejsintegration med en Jira-instans. Det gør det muligt at forbinde risici med Jira-problemer samt synkronisere deres data, status og kommentarer.',
    'APIExtraDesc'                        => 'API Extra giver kunderne mulighed for at bruge en RESTful API til at oprette scriptede interaktioner med andre applikationer for at opnå avanceret automatisering og udnytte eksisterende infrastruktur.',
    'AdvancedSearchExtraDesc'             => 'Extra-modulet Advanced Search forvandler søgefeltet i topbjælken til én søgning på tværs af risici, rammer, kontroller, dokumenter, undtagelser, tests, revisioner, aktiver og aktivgrupper med en komplet søgeside til at gennemgå resultaterne. Det viser kun poster, som brugeren har tilladelse til at se.',
    'AssessmentsExtraDesc'                => 'Extra-modulet Risk Assessment giver brugere mulighed for at definere kontakter, oprette spørgsmål (herunder logik), samle flere spørgsmål i en spørgeskemaskabelon, oprette spørgeskemaer og sende dem til kontakter, se spørgeskemaresultaterne, tilføje risici baseret på disse resultater, sammenligne resultaterne over tid, importere og eksportere eksternt tilpassede vurderinger samt gennemgå revisionssporet for risikovurderinger.',
    'ActiveAssessmentsDesc'               => 'Se og administrer vurderinger, der aktuelt er i gang.',
    'WorkflowsExtraDesc'                  => 'Extra-modulet Workflows leverer en visuel, hændelsesdrevet workflowmotor, der automatiserer handlinger inden for risikostyring som svar på hændelser i SimpleRisk. Du kan designe workflows, der udløses af ændringer — f.eks. at en risiko indsendes, opdateres eller gennemgås — for at route godkendelser, tildele arbejde og holde din proces i gang uden manuel indgriben.',

    // Configure Hub - tile descriptions (frameworks category)
    'SCFExtraDesc'                        => 'Secure Controls Framework (SCF) Extra er en direkte integration mellem Secure Controls Framework og SimpleRisk. Den importerer SCF\'s katalog over kontroller og deres kortlægninger på tværs af en lang række rammer for overholdelse og cybersikkerhed til SimpleRisks Governance-funktionalitet, så du kan tage de rammer i brug, du har brug for, og administrere deres kontroller uden at opbygge dem manuelt.',

    // Configure Hub - tile descriptions (maintenance category)
