    'SoaMissingScopeStatement' => 'Der er ikke registreret nogen afgrænsning for denne ramme. En SoA bør angive den afgrænsning, den udarbejdes for.',
    'SoaMissingInclusionJustification' => 'Der er ikke registreret nogen standardbegrundelse for inklusion. Anvendelige kontroller uden tilknyttede risici falder tilbage på en generisk erklæring i stedet for din egen.',
    'SoaEditFrameworkToAdd' => 'Tilføj dem på rammen',

    // Opened from the Reporting Hub, which cannot supply a framework. A picker,
