    'SoaFrameworkInactiveTitle' => 'Denne ramme er inaktiv',
    'SoaFrameworkInactiveBody' => 'En erklæring om anvendelighed beskriver den afgrænsning, som en organisation i øjeblikket arbejder under. Genaktivér rammen for at generere en.',
    'SoaFrameworkNotFoundBody' => 'Den ramme findes ikke længere.',

    // A framework with no controls mapped into it. Not an error -- it is a real
