    'SoaNoControls' => 'Denne ramme har ingen kontroller',
    'SoaNoControlsHint' => 'Tilknyt kontroller til rammen, så vil dens erklæring om anvendelighed vise dem.',

    // The second half of the statement-of-applicability launcher's affordance
