    'EnableCSPHelp' => 'Content Security Policy (CSP) begrænser browseren til kun at indlæse scripts, typografier, billeder og skrifttyper fra SimpleRisk selv og blokerer indramning af sider og formularindsendelser på tværs af oprindelser. Det er det stærkeste indbyggede forsvar mod cross-site scripting. Lad den være aktiveret, medmindre den er i konflikt med en proxy, browserudvidelse eller tredjepartsintegration i dit miljø.',
