    'AssetScoring' => 'Aktivscoring',
    'AssetScoringSettingsHint' => 'Hvert aktiv vurderes som Lav, Moderat eller Høj for fortrolighed, integritet og tilgængelighed, og fortrolighed kan i stedet være Ikke relevant, hvilket udelader den fra begge resultater. Aktivets FIPS-kategorisering er den højeste af de tre vurderinger. Dets vægtede score er det vægtede gennemsnit af de tre niveauværdier, og intervalgrænserne omsætter denne score til et Lavt, Moderat eller Højt interval. Hvis du ændrer disse indstillinger, scores alle aktiver straks igen.',
    'Weights' => 'Vægte',
    'AssetScoringWeightsHint' => 'Hvor meget hvert mål tæller i den vægtede score: 0 til 100, med op til to decimaler. En vægtning på 0 udelader det pågældende mål. Integritet og Tilgængelighed kan ikke begge være 0, fordi en "Ikke relevant" fortrolighed altid udelades.',
    'LevelValues' => 'Niveauværdier',
