    'AssetScoringScoreHelp' => 'Den vægtede score samler de tre vurderinger i ét tal fra {$low} til {$high}. Hver vurdering bliver til sin fastsatte værdi, og hver værdi ganges med vægten for det pågældende mål. Resultaterne lægges sammen og divideres med summen af vægtene. Fortrolighed med værdien Ikke relevant udelades sammen med sin vægt. De fastsatte værdier og vægte konfigureres under Præferencer. Alle tre mål skal vurderes, før en score vises.',
